{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT round(c.duration/1e6,1) AS seat_client_get_ms, round(s.duration/1e6,1) AS config_server_ms, round((epoch_ms(c.time)+c.duration/1e6)-(epoch_ms(s.time)+s.duration/1e6),1) AS client_end_after_server_end_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND c.span_id=s.parent_span_id WHERE c.service_name='ts-seat-service' AND c.span_name='GET' AND s.service_name='ts-config-service' ORDER BY c.duration DESC LIMIT 12",
          "claim": "Seat's GET calls to config take ~2.4s on the client, while config's server span takes ~4ms; the delay is after config responds."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' GROUP BY ALL ORDER BY span_name",
          "claim": "Seat's other outbound POST calls (order, order-other) stay at about 8ms p95, so only the config GET path is slow."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, count(*) n, round((max(value)-min(value))/greatest(1,(epoch(max(time))-epoch(min(time)))/60),1) per_min FROM abnormal_metrics_sum WHERE metric = 'hubble_tcp_flags_total' AND attr_source LIKE '%seat%' AND attr_destination LIKE '%config%' GROUP BY ALL",
          "claim": "Seat-to-config TCP flag counts show no retransmit or drop surge on the connection, consistent with a healthy connection and an application-level hold."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-service' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Travel-service's calls to seat show about 2.4s p95, inherited from the seat delay."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel2-service' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Travel2-service's calls to seat show about 2.4s p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Travel-plan-service's calls to seat show about 2.4s p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "Route-plan's calls to travel-service take about 13.9s p95, up from milliseconds, inheriting the seat delay."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel2-service' GROUP BY ALL",
          "claim": "Route-plan's calls to travel2-service take about 5.6s p95, inheriting the seat delay."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Travel-plan's calls to route-plan take about 19.9s p95, versus normal sub-second times."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.95),1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "Ui-dashboard's calls to travel-plan rise to tens of seconds p95, so the user-facing dashboard sees the delay."
        }
      ]
    }
  ]
}
